export function atoi(text: string): number {
let i=0;while(text[i]===" ")i++;let sign=1;if(text[i]==="-"||text[i]==="+"){if(text[i]==="-")sign=-1;i++;}let n=0;while(i<text.length&&text[i]>="0"&&text[i]<="9"){n=Math.min(2147483648,n*10+Number(text[i++]));}return Math.max(-2147483648,Math.min(2147483647,sign*n))||0;
}
